    public async PrintDailyBillReport(apiReq?: ApiRequest<PatientBillsFilters>): Promise<any> {
        let data = await this.GetPatientBillswithoutdetails(apiReq);
        let PatientBills = data.Data;
        let FromDate = apiReq.Data.FromDate;
        let ToDate = apiReq.Data.ToDate;
        let FacilityName = apiReq.Data.FacilityName;
        let UserName = apiReq.Data.UserName;
        let PatientBillsData = data.Data[0];
        let PatientDailyBills: any = [];
        PatientBills.forEach((Detail: any) => {
            let BillData = Detail;
            BillData.NetAmount = parseInt(Detail.BillAmount) - parseInt(Detail.BillDiscount);
            PatientDailyBills.push(BillData);
        });
        let facilityPreferenceBO = BoFactory.GetBo(userbo.FacilityPreferenceBo, this.Request);
        let printPreferencesData =
            await facilityPreferenceBO.GetFacilityPreferenceWithLogo(PatientBillsData.FacilityId);
        let info = {
            PatientBills: PatientDailyBills,
            Preferences: printPreferencesData,
            FromDate: FromDate,
            ToDate: ToDate,
            FacilityName: FacilityName,
            UserName: UserName
        };
        let pdfOption: any = null;
        let key = 'dailybillreport';
        let pdfOptionJSON = await Report.GetPdfOption(key);
        if (!pdfOptionJSON) {
            pdfOption = {
                format: 'A4',
                orientation: 'portrait',
                border: '0',
                header: {
                    height: '1.5in',
                    contents: '',
                },
                footer: {
                    height: '0.5in',
                    contents: {
                        first: '',
                        default: '',
                        last: '',
                    },
                },
                type: 'pdf',
                base: 'file://' + join(__dirname, '/../../Templates/assets/')
            };
        } else {
            pdfOption = JSON.parse(pdfOptionJSON);
            pdfOption.base = 'file://' + join(__dirname, '/../../Templates/assets/');
        }
        return await Report.Generate(key, { header: {}, body: info }, null, pdfOption);
    }
