            TotalBillAmount += item.BillAmount;
            TotalDisAmount += item.BillDiscount;
            TotalNetAmount += item.NetAmount;
            TotalPaidAmount += item.PaidAmount;
            TotalDueAmount += item.OutStandingAmount;
