    public async getPharmacyBillsWithReturn(req: BaseRequest): Promise<any> {
        let PharmacyBillsWithReturn: any = [];
        let apiReq = {
            Id: 0,
            PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientBillsFilters.OnlyPID, Value: req.Data.PatientId },
            { Key: PatientBillsFilters.IsPharmacyBill, Value: true },
            { Key: PatientBillsFilters.FromDate, Value: req.Data.FromDate },
            { Key: PatientBillsFilters.ToDate, Value: req.Data.ToDate },
            { Key: PatientBillsFilters.PharmacySaleTypeId, Value: req.Data.PharmacySaleTypeId },
            { Key: PatientBillsFilters.EncounterId, Value: req.Data.EncounterId },
            { Key: PatientBillsFilters.PrivateDueId, Value: req.Data.DueApprovedById },
            { Key: PatientBillsFilters.StoreMasterId, Value: req.Data.StoreMasterId }]
        };
        if (req.Data.IsOutStanding === true) {
            apiReq.Params.push({ Key: PatientBillsFilters.IsOutStanding, Value: req.Data.IsOutStanding });
        }
        if (req.Data.NotOutStanding === true) {
            apiReq.Params.push({ Key: PatientBillsFilters.NotOutStanding, Value: req.Data.NotOutStanding });
        }
        if (req.Data.VisitIdentifier) {
            apiReq.Params.push({ Key: PatientBillsFilters.VisitIdentifier, Value: req.Data.VisitIdentifier });
        }
        let PatientBillsData = await this.GetPatientBills(apiReq);
        let PatientBillIds = Array();
        if (PatientBillsData) {
            for (var i = 0; i < PatientBillsData.Data.length; i++) {
                let PatientBills = PatientBillsData.Data[i];
                PharmacyBillsWithReturn.push(PatientBills);
                PatientBillIds.push(PatientBillsData.Data[i].Id);
            }
        }

        let PatientReturnReq = {
            Id: 0,
            PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientReturnsFilters.OnlyPID, Value: req.Data.PatientId },
            { Key: PatientReturnsFilters.FromDate, Value: req.Data.FromDate },
            { Key: PatientReturnsFilters.ToDate, Value: req.Data.ToDate },
            { Key: PatientReturnsFilters.EncounterId, Value: req.Data.EncounterId },
            { Key: PatientReturnsFilters.PharmacyReturnType, Value: req.Data.PharmacySaleTypeId },
            { Key: PatientReturnsFilters.StoreMasterId, Value: req.Data.StoreMasterId }
            ]
        };
        if (req.Data.VisitIdentifier) {
            PatientReturnReq.Params.push({ Key: PatientReturnsFilters.VisitIdentifier, Value: req.Data.VisitIdentifier });
        }
        if (req.Data.IsOutStanding === true) {
            PatientReturnReq.Params.push({ Key: PatientReturnsFilters.PatientBillId, Value: PatientBillIds });
        }
        if (req.Data.NotOutStanding === true) {
            PatientReturnReq.Params.push({ Key: PatientReturnsFilters.PatientBillId, Value: PatientBillIds });
        }
        let PatientReturnsBo = BoFactory.GetBo(bo.PatientReturnsBo, this.Request);
        let PatientReturnsData = await PatientReturnsBo.GetPatientReturns(PatientReturnReq);
        if (PatientReturnsData) {
            for (var j = 0; j < PatientReturnsData.Data.length; j++) {
                let PatientReturns = PatientReturnsData.Data[j];
                PharmacyBillsWithReturn.push(PatientReturns);
            }
        }
        return PharmacyBillsWithReturn;
    }

