        // BillDetailsData.Data.forEach((Detail: any) => {
        for (let bdx in BillDetailsData.Data) {
            let PatientBillDetail: any = BillDetailsData.Data[bdx];
            if (PatientBillDetail.GrossAmount > 0) {
                PatientBillDetail.Amt = PatientBillDetail.InGstAmount -
                    (PatientBillDetail.CGstAmount + PatientBillDetail.SGstAmount);
                let ordDetailReq = {
                    Id: 0,
                    PageContext: { PageSize: -1, PageNumber: 1 },
                    Params: [{ Key: PatientOrderDetailFilters.PatientBillDetailId, Value: PatientBillDetail.Id }]
                };
                let PatientOrderDetailBo = BoFactory.GetBo(emrbo.PatientOrderDetailBo, this.Request);
                let OrderDetails = await PatientOrderDetailBo.GetPatientOrderDetails(ordDetailReq);
                if (OrderDetails.Data.length > 0) {
                    for (let odx in OrderDetails.Data) {
                        let ordData = OrderDetails.Data[odx];
                        // let orderReq = {
                        //     Id: 0,
                        //     PageContext: { PageSize: -1, PageNumber: 1 },
                        //     Params: [{ Key: PatientOrderFilters.Id, Value: ordData.PatientOrderId }]
                        // };
                        let PatientOrderBO = BoFactory.GetBo(emrbo.PatientOrderBo, this.Request);
                        let PatientOrder = await PatientOrderBO.GetPatientOrderById({ Id: ordData.PatientOrderId });
                        if (PatientOrder) {
                            PatientBillDetail.OrderNumber = PatientOrder.OrderNumber;
                        }
                    }

                }
                BillDetails.push(PatientBillDetail);
            }
        }
        // let PatientBillDetail = Detail;
        // let ordDetailReq = {
        //     Id: 0,
        //     PageContext: { PageSize: -1, PageNumber: 1 },
        //     Params: [{ Key: PatientOrderDetailFilters.PatientBillDetailId, Value: PatientBillDetail.Id }]
        // };
        // let PatientOrderDetailBo = BoFactory.GetBo(emrbo.PatientOrderDetailBo, this.Request);
        // let OrderDetails = await PatientOrderDetailBo.GetPatientOrderDetails(ordDetailReq);

        // });
        let detailReq = {
            Id: 0,
            PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientPaymentDetailsFilters.PatientBillId, Value: req.Id },
            { Key: PatientPaymentDetailsFilters.ReceiptStatus, Value: 1 }]
        };
        let PatientPaymentDetailsData = await PatientPaymentDetailsBo.GetPatientPaymentDetails(detailReq);
        let refundReq = {
            Id: 0,
            PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientRefundFilters.PatientBillId, Value: req.Id },
            { Key: PatientRefundFilters.RefundStatus, Value: 1 }]
        };
        let PatientRefundData = await PatientRefundBo.GetPatientRefund(refundReq);
        let ordReq = {
            Id: 0,
            PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientOrderFilters.PatBillingId, Value: PatientBills.Id }]
        };
        let orderBo = BoFactory.GetBo(emrbo.PatientOrderBo, this.Request);
        let OrderData = await orderBo.GetPatientOrderWithoutDetails(ordReq);
        let OrderInfo: any = OrderData.Data[0];
        //Get print preferences
        let facilityPreferenceBO = BoFactory.GetBo(userbo.FacilityPreferenceBo, this.Request);
        let printPreferencesData =
            await facilityPreferenceBO.GetFacilityPreferenceWithLogo(PatientBills.FacilityId);
        //Preferences: printPreferencesData
        let QrInfo: any;
        let PatName: '';
        let FacInfo: '';
        if (patientinfo.Title) {
            PatName = patientinfo.Title.Description;
        }
        if (patientinfo.FirstName) {
            PatName += ' ' + patientinfo.FirstName;
        }
        if (patientinfo.LastName) {
            PatName += ' ' + patientinfo.LastName;
        }
        if (PatientBills.Facility) {
            FacInfo = PatientBills.Facility.FacilityName;
        }
        if (PatientBills.Facility.AddressLine1) {
            FacInfo += ', ' + PatientBills.Facility.AddressLine1;
        }
        if (PatientBills.Facility.Mobile) {
            FacInfo += ',Phone: ' + PatientBills.Facility.Mobile;
        }
        if (PatientBills.Facility.Email) {
            FacInfo += ',Email: ' + PatientBills.Facility.Email;
        }
        if (PatientBills.Facility.GstNumber) {
            FacInfo += ',GSTIN No: ' + PatientBills.Facility.GstNumber;
        }

        QrInfo = PatientBills.BillNumber + ' , ' + PatientBills.BillAmount + ' , ' +
            PatientBills.BillDateTime + ' , ' + PatName + ' , ' + FacInfo;
        let info = {
            PatientBills: PatientBills,
            BillDetails: BillDetails,
            PatientPaymentDetails: PatientPaymentDetailsData.Data,
            PatientRefund: PatientRefundData.Data,
            Encounter: encounterData.Data[0],
            Referrals: ReferralsData.Data[0],
            NetAmount: (PatientBills.BillAmount + PatientBills.RoundOffValue) -
                (PatientBills.BillDiscount || 0) - (PatientBills.RefundAmount || 0) + (PatientBills.GSTAmount || 0),
            PatientGuarantor: PatientGuarantorsData.Data[0],
            Age: Age,
            Preferences: printPreferencesData,
            QrInfo: QrInfo,
            OrderInfo: OrderInfo,
            CancelledAmt: CancelledAmt,
            Flags: flags
        };

        let key = 'outpatientbill';
        let Watermark = '';
        let PrintTypeId: number;
        if (info.PatientBills.PatientBillStatusId === 2) {
            Watermark = 'CANCELLED';
            PrintTypeId = 2;
        }
        if (info.PatientBills.BillTypeId === 5) {
            key = 'dgbilling';
            if (info.PatientBills.PatientBillStatusId === 2) {
                Watermark = 'CANCELLED';
                PrintTypeId = 2;
            }
        }
        if (info.PatientBills.BillTypeId === 1
            && info.PatientBills.IsPaidFully === false && info.PatientBills.OutStandingAmount > 0) {
            key = 'outpatientbill';
        }
        let pdfOption: any = null;
        // let reportKey = 'ippharmacyjson';
        let pdfOptionJSON = await Report.GetPdfOption(key);
        if (!pdfOptionJSON) {
            pdfOption = {
                format: 'A4',
                orientation: 'portrait',
                border: '0',
                header: {
                    height: '1in',
                    contents: '',
                },
                footer: {
                    height: '1in',
                    contents: {
                        first: '',
                        default: '',
                        last: '',
                    },
                    // height: '5.8in',
                    // width: '8.3in',
                    // orientation: 'landscape',
                    // border: '0',
                    // header: {
                    //     height: '0.7in',
                    //     contents: '',
                    // },
                    // footer: {
                    //     height: '0.5in',
                    //     contents: {
                    //         first: '',
                    //         default: '',
                    //         last: '',
                    //     },
                },
                type: 'pdf',
                base: 'file://' + join(__dirname, '/../../Templates/assets/')
            };
            let printInfo = {
                ObjectId: req.Id
                , ObjectTypeId: 4 /*Order*/
                , Reason: req.Data ? req.Data.Reason : null
                , Watermark: Watermark  /* Provide watermark, if needed other than DUPLICATE */
                , PrintTypeId: PrintTypeId /* Provide 2, if needed watermark all time i.e., CONFIDENTIAL */
            };
            let ephBO = BoFactory.GetBo(generalBO.EntityPrintHistoryBo, this.Request);
            let entityPrintHistoryData = await ephBO.ManagePrintHistory(printInfo);
            if ((printInfo.PrintTypeId === 2 || entityPrintHistoryData.PrintTypeId === 2) && isduplicate) {
                Watermark = Watermark || 'DUPLICATE';
            }
        } else {
            let printInfo = {
                ObjectId: req.Id
                , ObjectTypeId: 4 /*Order*/
                , Reason: req.Data ? req.Data.Reason : null
                , Watermark: Watermark  /* Provide watermark, if needed other than DUPLICATE */
                , PrintTypeId: PrintTypeId /* Provide 2, if needed watermark all time i.e., CONFIDENTIAL */
            };
            let ephBO = BoFactory.GetBo(generalBO.EntityPrintHistoryBo, this.Request);
            let entityPrintHistoryData = await ephBO.ManagePrintHistory(printInfo);
            if ((printInfo.PrintTypeId === 2 || entityPrintHistoryData.PrintTypeId === 2) && isduplicate) {
                Watermark = Watermark || 'DUPLICATE';
            }
            pdfOption = JSON.parse(pdfOptionJSON);
            pdfOption.base = 'file://' + join(__dirname, '/../../Templates/assets/');
            // console.log(pdfOption);
        }
        return await Report.Generate(key, { header: {}, body: info, watermark: Watermark },
            null, pdfOption);
        // return await Report.Generate(key, { header: {}, body: info });
        // let ephBO = BoFactory.GetBo(generalBO.EntityPrintHistoryBo, this.Request);
        // return await ephBO.PrintReport(key
        //     , { header: {}, body: info }
