    public async OPRevenueDetails(req: BaseRequest): Promise<any> {
        let OPBillResult: any = {};
        let netamt = 0;
        OPBillResult['DisplayOrder'] = 1;
        let opbillamountInstance: any = await this.FindAll({
            attributes: ['BillAmount', 'BillDiscount', 'DepartmentId'],
            where: {
                BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                PatientBillStatusId: 3,
                IsPharmacyBill: 0,
                BillTypeId: { '$in': [1, 5] },
                FacilityId: req.Data.FacilityId
            }
        });
        if (opbillamountInstance) {
            for (let i = 0; i < opbillamountInstance.length; i++) {
                let bills: any = this.GetAttribute(opbillamountInstance[i]);
                // let DeptId = bills.DepartmentId;
                let billamt = bills.BillAmount;
                let discbill = bills.BillDiscount;
                let NetAmount = billamt - discbill;
                netamt += NetAmount;
            }
            // let bill: any = this.GetAttribute(opbillamountInstance);
            OPBillResult['BillAmt'] = netamt;
        }
        return OPBillResult;
    }
