    public async IPPharmacyBills(req: BaseRequest): Promise<any> {
        let UserGroup: { [id: number]: any[] } = {};
        let UserGroupJoin: any = {
            model: this.Models.User, as: 'CreatedUser',
            attributes: ['FirstName', 'LastName', 'UserName'],
            required: true,
            include: [
                this.GetReference('Title')
            ]
        };
        let totalbillamountInstance: any = await this.FindAll({
            attributes: ['BillAmount', 'BillGeneratedBy'],
            where: {
                // BillTypeId: 3,
                BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                PatientBillStatusId: 3,
                IsPharmacyBill: 1,
                Status: 1,
                FacilityId: req.Data.FacilityId,
                StoreMasterId: req.Data.StoreMasterId,
                BillGeneratedBy: { '$gt': 0 },
            },
            include: [UserGroupJoin]
        });
        if (totalbillamountInstance) {
            let groupbills = _.groupBy(totalbillamountInstance, 'BillGeneratedBy');
            for (let i in groupbills) {
                let groupedBills = groupbills[i];
                let BillAmount: number = 0;
                let UserId: number = 0;
                let User: string = '';
                for (let i = 0; i < groupedBills.length; i++) {
                    let bills: any = groupedBills[i];
                    BillAmount += bills.BillAmount;
                    UserId = bills.BillGeneratedBy;
                    User = bills.CreatedUser;
                    UserGroup[UserId] = UserGroup[UserId] || [];
                }
                let info = {
                    'TotalBillAmt': BillAmount,
                    'UserId': UserId,
                    'UserName': User
                };
                UserGroup[UserId].push(info);
            }
        }
        let dueamountInstance: any = await this.FindAll({
            attributes: ['BillAmount', 'OutStandingAmount', 'BillGeneratedBy'],
            where: {
                // BillTypeId: 3,
                BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                PatientBillStatusId: 3,
                IsPharmacyBill: 1,
                Status: 1,
                FacilityId: req.Data.FacilityId,
                StoreMasterId: req.Data.StoreMasterId,
                BillGeneratedBy: { '$gt': 0 },
            },
            include: [UserGroupJoin]
        });
        if (dueamountInstance) {
            let groupbills = _.groupBy(dueamountInstance, 'BillGeneratedBy');
            for (let i in groupbills) {
                let groupedBills = groupbills[i];
                let DueAmount: number = 0;
                let UserId: number = 0;
                let User: string = '';
                for (let i = 0; i < groupedBills.length; i++) {
                    let bills: any = groupedBills[i];
                    DueAmount += bills.OutStandingAmount;
                    UserId = bills.BillGeneratedBy;
                    User = bills.CreatedUser;
                    UserGroup[UserId] = UserGroup[UserId] || [];
                }
                let info = {
                    'BalanceDue': DueAmount,
                    'UserId': UserId,
                    'UserName': User
                };
                UserGroup[UserId].push(info);
            }
        }
        let ipbillamountInstance: any = await this.FindAll({
            attributes: ['BillAmount', 'BillGeneratedBy'],
            where: {
                BillTypeId: 3,
                BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                PatientBillStatusId: 3,
                IsPharmacyBill: 1,
                Status: 1,
                FacilityId: req.Data.FacilityId,
                BillGeneratedBy: { '$gt': 0 },
                StoreMasterId: req.Data.StoreMasterId,
                PharmacySaleTypeId: 6
            },
            include: [UserGroupJoin]
        });
        if (ipbillamountInstance) {
            let groupbills = _.groupBy(ipbillamountInstance, 'BillGeneratedBy');
            for (let i in groupbills) {
                let groupedBills = groupbills[i];
                let BillAmount: number = 0;
                let UserId: number = 0;
                let User: string = '';
                for (let i = 0; i < groupedBills.length; i++) {
                    let bills: any = groupedBills[i];
                    BillAmount += bills.BillAmount;
                    UserId = bills.BillGeneratedBy;
                    User = bills.CreatedUser;
                    UserGroup[UserId] = UserGroup[UserId] || [];
                }
                let info = {
                    'IPSaleAmount': BillAmount,
                    'UserId': UserId,
                    'UserName': User
                };
                UserGroup[UserId].push(info);
            }
        }
        return UserGroup;
    }
