    public async OverallBills(req: BaseRequest): Promise<any> {
        let UserGroup: { [id: number]: any[] } = {};
        let UserGroupJoin: any = {
            model: this.Models.User, as: 'CreatedUser',
            attributes: ['FirstName', 'LastName', 'UserName'],
            required: true,
            include: [
                this.GetReference('Title')
            ]
        };
        if (req.Data.UserId > 0) {
            let totalbillamountInstance: any = await this.FindAll({
                attributes: ['BillAmount', 'BillGeneratedBy'],
                where: {
                    BillTypeId: { '$in': [1, 2, 4, 5] },
                    BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                    PatientBillStatusId: 3,
                    // IsPharmacyBill: 0,
                    Status: 1,
                    FacilityId: req.Data.FacilityId,
                    BillGeneratedBy: { '$eq': req.Data.UserId },
                },
                include: [UserGroupJoin]
            });
            if (totalbillamountInstance) {
                let groupbills = _.groupBy(totalbillamountInstance, 'BillGeneratedBy');
                for (let i in groupbills) {
                    let groupedBills = groupbills[i];
                    let BillAmount: number = 0;
                    let UserId: number = 0;
                    let User: string = '';
                    for (let i = 0; i < groupedBills.length; i++) {
                        let bills: any = groupedBills[i];
                        BillAmount += bills.BillAmount;
                        UserId = bills.BillGeneratedBy;
                        User = bills.CreatedUser;
                        UserGroup[UserId] = UserGroup[UserId] || [];
                    }
                    let info = {
                        'TotalBillAmt': BillAmount,
                        'UserId': UserId,
                        'UserName': User
                    };
                    UserGroup[UserId].push(info);
                }
            }
        } else if (req.Data.UserId === 0) {
            let totalbillamountInstance: any = await this.FindAll({
                attributes: ['BillAmount', 'BillGeneratedBy'],
                where: {
                    BillTypeId: { '$in': [1, 2, 4, 5] },
                    BillDateTime: { '$gt': req.Data.FromDate, '$lte': req.Data.ToDate },
                    PatientBillStatusId: 3,
                    // IsPharmacyBill: 0,
                    Status: 1,
                    FacilityId: req.Data.FacilityId,
                    BillGeneratedBy: { '$gt': req.Data.UserId },
                },
                include: [UserGroupJoin]
            });
            if (totalbillamountInstance) {
                let groupbills = _.groupBy(totalbillamountInstance, 'BillGeneratedBy');
                for (let i in groupbills) {
                    let groupedBills = groupbills[i];
                    let BillAmount: number = 0;
                    let UserId: number = 0;
                    let User: string = '';
                    for (let i = 0; i < groupedBills.length; i++) {
                        let bills: any = groupedBills[i];
                        BillAmount += bills.BillAmount;
                        UserId = bills.BillGeneratedBy;
                        User = bills.CreatedUser;
                        UserGroup[UserId] = UserGroup[UserId] || [];
                    }
                    let info = {
                        'TotalBillAmt': BillAmount,
                        'UserId': UserId,
                        'UserName': User
                    };
                    UserGroup[UserId].push(info);
                }
            }
        }
        return UserGroup;
    }

