    public async checkBillCashAmount(req: any): Promise<any> {
        const encounterId = req.Data.Header.EncounterId;
        let NetAmount = 0, AmountPaid = 0, RefundAmount = 0;

        const billDetailsBo = BoFactory.GetBo(bo.PatientBillDetailsBo, this.Request);
        const billRes = await billDetailsBo.GetMinPatientBillDetailsforLock({
            Id: 0, PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [
                { Key: PatientBillDetailsFilters.EncounterId, Value: encounterId },
                { Key: PatientBillDetailsFilters.IsTempIPBill, Value: true }]
        });

        if (billRes.Data && billRes.Data.length > 0) {
            for (const item of billRes.Data) {
                if (item.PatientBillStatusId === 3) {
                    NetAmount += (item.GrossAmount || 0) - ((item.DiscountAmount || 0) + (item.ProportionateDiscount || 0));
                }
            }
        }

        const paymentBo = BoFactory.GetBo(bo.PatientPaymentDetailsBo, this.Request);
        const payRes = await paymentBo.GetMinPatientPaymentDetailsforLock({
            Id: 0, PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientPaymentDetailsFilters.EncounterId, Value: encounterId }]
        });

        if (payRes.Data && payRes.Data.length > 0) {
            for (const p of payRes.Data) {
                if (p.ReceiptStatusId === 1 && p.IsPharmacyReceipt === false)
                    AmountPaid += (p.AmountPaid || 0);
            }
        }

        const refundBo = BoFactory.GetBo(bo.PatientRefundBo, this.Request);
        const refundRes = await refundBo.GetPatientRefund({
            Id: 0, PageContext: { PageSize: -1, PageNumber: 1 },
            Params: [{ Key: PatientRefundFilters.EncounterId, Value: encounterId }]
        });

        if (refundRes.Data && refundRes.Data.length > 0) {
            for (const r of refundRes.Data) {
                if (r.PharmacyReturnId === null && r.RefundStatusId === 1)
                    RefundAmount += (r.RefundAmount || 0);
            }
        }

        console.log(NetAmount);
        console.log(AmountPaid);
        console.log(RefundAmount);
        const BalanceAmount = NetAmount - (AmountPaid - RefundAmount);
        // return BalanceAmount > 0 ? BalanceAmount : 0;
        return BalanceAmount;
    }

