    private async registerPatientIfNeeded(req: BaseRequest, session: any): Promise<number | null> {
        const patientBo = BoFactory.GetBo(regbo.PatientBo, this.Request);
        const memberData: any = {
            Data: {
                Id: 0,
                MRNTypeId: 1,
                NationalityId: req.Data.Header.NationalityId,
                TitleId: req.Data.Header.TitleId || 0,
                PatientName: req.Data.Header.PatientName,
                FirstName: req.Data.Header.PatientName,
                DOB: req.Data.Header.DOB,
                GenderId: req.Data.Header.GenderId,
                Mobile: req.Data.Header.Mobile,
                Email: req.Data.Header.Email,
                IsActive: true,
                CreatedBy: session.UserId,
                CreatedOn: new Date(),
                IsEmergency: true,
                FacilityId: session.FacilityId,
                Address: req.Data.Header.Address,
                Age: req.Data.Header.Age,
                AgeUnitId: req.Data.Header.AgeUnitId,
                From: 'fromjssdirectsales',
                PatientStatus: 'Active'
            }
        };

        const patientId: any = await patientBo.AddPatient(memberData);
        return patientId > 0 ? patientId : null;
    }

    private async UpdatePlanInfo(req: any) {
        console.log('NEWLY GENERATED ' + req.Data.Header.BillNumber);
        let planBO = BoFactory.GetBo(emrbo.TreatmentPlanBo, this.Request);
        let orderUpdateBillNr: any = { BillNumber: req.Data.Header.BillNumber };
        await planBO.Update(orderUpdateBillNr, {
            fields: ['BillNumber'],
            where: {
                PatientBillId: req.Data.Header.PatientBillId
            }
        });

    }

    private async UpdateOrderInfo(req: any) {
        console.log('NEWLY GENERATED ' + req.Data.Header.BillNumber);
        let patorderBo = BoFactory.GetBo(emrbo.PatientOrderBo, this.Request);
        if (req.Data.Header.OrderIds) {
            if (req.Data.Header.OrderIds.length > 0) {
                for (let odx in req.Data.Header.OrderIds) {
                    let orderId = req.Data.Header.OrderIds[odx];
                    let PatientOrder = await patorderBo.GetPatientOrderById({ Id: orderId });
                    PatientOrder.BillingId = req.Data.Header.PatientBillId;
                    PatientOrder.BillNumber = req.Data.Header.BillNumber;
                    await patorderBo.Update(PatientOrder);
                }
            }
        } else {
            let orderUpdateBillNr: any = { BillNumber: req.Data.Header.BillNumber };
            await patorderBo.Update(orderUpdateBillNr, {
                fields: ['BillNumber'],
                where: {
                    BillingId: req.Data.Header.PatientBillId
                }
            });
        }
    }

    private async UpdatePatientAccountsInfo(req: any) {
        console.log('NEWLY GENERATED ' + req.Data.Header.BillNumber);
        let patientaccountsBO = BoFactory.GetBo(billingBO.PatientAccountsBo, this.Request);
        let accountUpdateBillNr: any = { TransactionNumber: req.Data.Header.BillNumber };
        await patientaccountsBO.Update(accountUpdateBillNr, {
            fields: ['TransactionNumber'],
            where: {
                TransactionTypeId: 2,
                TransactionId: req.Data.Header.PatientBillId,
                TransactionNumber: null,
            }
        });
    }

